import json, re

DETECTION_PATTERNS = [
    (r'\b(?:wrong|error|mistake|incorrect|unexpected)\b', 'wrong/error/mistake'),
    (r'\b(?:strange|odd|confused|confusing|inconsistent)\b', 'strange/odd/confused'),
    (r\"(?:doesn'?t\s+match|doesn'?t\s+make\s+sense|not\s+right)\", 'doesnt_match/not_right'),
    (r'\b(?:something\s+(?:is\s+)?(?:off|wrong)|went\s+wrong)\b', 'something_wrong'),
    (r'\b(?:missing|lost|truncated|disappeared)\b', 'missing/lost'),
    (r'\b(?:should\s+have|need\s+to\s+redo|go\s+back|try\s+again)\b', 'should_have/go_back'),
    (r'\b(?:problem|issue|anomal)', 'problem/issue'),
    (r'\b(?:wait|hmm)\b.*\b(?:but|however|actually)\b', 'wait_but'),
]

files = {
    'vanilla': 'eval_results/llama31_vanilla_s42.json',
    'taxei': 'eval_results/llama31_taxei_s42.json',
    'random': 'eval_results/llama31_random_s42.json',
}

# Also count pattern matches
pattern_counts = {cond: {name: 0 for _, name in DETECTION_PATTERNS} for cond in files}
go_back_only = {cond: 0 for cond in files}
total_det = {cond: 0 for cond in files}

for cond, fpath in files.items():
    with open(fpath) as f:
        data = json.load(f)

    print(f'\\n===== {cond.upper()} =====')

    for i, ep in enumerate(data['episodes']):
        if not ep['recovery_analysis']['detected']:
            continue
        total_det[cond] += 1

        # Collect all detected think texts
        ep_patterns = set()
        for step in ep['trajectory']:
            if step['detected_error']:
                text = step['think_snippet'].lower()
                matched = []
                for pat, name in DETECTION_PATTERNS:
                    if re.search(pat, text):
                        matched.append(name)
                        pattern_counts[cond][name] += 1
                        ep_patterns.add(name)

                print(f'  Ep{i} step{step[\"step\"]} [{ep[\"operator\"]}]: {matched}')
                # Show the exact matching text
                for pat, name in DETECTION_PATTERNS:
                    m = re.search(pat, text)
                    if m:
                        start = max(0, m.start()-20)
                        end = min(len(text), m.end()+20)
                        print(f'    -> {name}: ...{text[start:end]}...')

        if ep_patterns == {'should_have/go_back'}:
            go_back_only[cond] += 1

print('\\n\\n===== SUMMARY =====')
for cond in files:
    print(f'\\n{cond}: {total_det[cond]} detected episodes, {go_back_only[cond]} ONLY matched go_back')
    for _, name in DETECTION_PATTERNS:
        if pattern_counts[cond][name] > 0:
            print(f'  {name}: {pattern_counts[cond][name]} step-level matches')
"
